import React from "react";

export default function SpiritualRoutineCard({
  japDone,
  setJapDone,
  selfCheck,
  setSelfCheck
}) {
  const toggleCheck = (key) => {
    setSelfCheck({ ...selfCheck, [key]: !selfCheck[key] });
  };

  return (
    <div style={card}>
      <h3>🧭 Daily Spiritual Routine</h3>

      <h4>📿 Naam Jap (Non-Negotiable)</h4>
      <button
        onClick={() => setJapDone(!japDone)}
        style={{
          ...btn,
          background: japDone ? "#4caf50" : "#e0e0e0"
        }}
      >
        {japDone ? "✔️ 1 Mala Done" : "❌ Not Done"}
      </button>

      <h4>🔹 Self Check (No guilt)</h4>

      <label>
        <input
          type="checkbox"
          checked={selfCheck.jap}
          onChange={() => toggleCheck("jap")}
        />
        Aaje jap thayu?
      </label>

      <label>
        <input
          type="checkbox"
          checked={selfCheck.satsang}
          onChange={() => toggleCheck("satsang")}
        />
        Satsang joyu?
      </label>

      <label>
        <input
          type="checkbox"
          checked={selfCheck.mobile}
          onChange={() => toggleCheck("mobile")}
        />
        Mobile control?
      </label>
    </div>
  );
}

const card = {
  border: "1px solid #ddd",
  padding: "15px",
  borderRadius: "10px",
  marginBottom: "15px"
};

const btn = {
  padding: "10px",
  border: "none",
  borderRadius: "8px",
  marginBottom: "10px",
  cursor: "pointer"
};
